+const { useState, useRef } = React;
+
+function ConsentForm() {
+  const [agreed, setAgreed] = useState(false);
+  const [error, setError] = useState("");
+  const [submitted, setSubmitted] = useState(false);
+  const checkboxRef = useRef(null);
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    if (!agreed) {
+      setError("You must agree to the terms of use to continue.");
+      setSubmitted(false);
+      checkboxRef.current && checkboxRef.current.focus();
+      return;
+    }
+    setError("");
+    setSubmitted(true);
+  };
+
+  const handleChange = (e) => {
+    setAgreed(e.target.checked);
+    if (e.target.checked) setError("");
+  };
+
+  const describedBy = ["terms-helper", error ? "terms-error" : null]
+    .filter(Boolean)
+    .join(" ");
+
+  return (
+    <section className="card" aria-labelledby="form-title">
+      <h1 id="form-title">Create your account</h1>
+      <p className="intro">Review and agree to our terms before continuing.</p>
+
+      <form noValidate onSubmit={handleSubmit}>
+        <div className={"form-field" + (error ? " is-invalid" : "")}>
+          <input
+            id="agree-terms"
+            ref={checkboxRef}
+            type="checkbox"
+            required
+            checked={agreed}
+            onChange={handleChange}
+            aria-describedby={describedBy}
+            aria-invalid={error ? "true" : "false"}
+          />
+          <label htmlFor="agree-terms">
+            I agree to the <a href="/terms">Terms of Use</a>
+            <span className="required" aria-hidden="true">*</span>
+          </label>
+          <p id="terms-helper" className="helper">
+            Required. By checking this box, you confirm you have read and accept our terms.
+          </p>
+          {error && (
+            <p id="terms-error" className="error" role="alert">
+              {error}
+            </p>
+          )}
+        </div>
+
+        <button type="submit">Submit</button>
+
+        {submitted && (
+          <p className="status" role="status">
+            Thanks — your agreement has been recorded.
+          </p>
+        )}
+      </form>
+    </section>
+  );
+}
+
+const root = ReactDOM.createRoot(document.getElementById("root"));
+root.render(<ConsentForm />);
+
')

